mapper.update:
update wo_order
category_id = #{categoryId}, premise_id = #{premiseId}, resident_id = #{residentId}, title = #{title}, description = #{description}, priority = #{priority}, status = #{status}, source = #{source}, sla_rule_id = #{slaRuleId}, response_deadline = #{responseDeadline}, resolve_deadline = #{resolveDeadline}, expect_time = #{expectTime}, assignee_id = #{assigneeId}, dispatcher_id = #{dispatcherId}, accept_time = #{acceptTime}, start_time = #{startTime}, finish_time = #{finishTime}, complete_time = #{completeTime}, cancel_time = #{cancelTime}, total_amount = #{totalAmount}, response_breached = #{responseBreached}, resolve_breached = #{resolveBreached}, is_rework = #{isRework}, rework_count = #{reworkCount}, rating = #{rating}, comment = #{comment}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select 


    and o.order_no like concat('%', #{orderNo}, '%')
    and o.title like concat('%', #{title}, '%')
    and o.category_id = #{categoryId}
    and o.status = #{status}
    and o.priority = #{priority}
    and o.assignee_id = #{assigneeId}
    and o.resident_id = #{residentId}
    and o.premise_id = #{premiseId}
    and o.create_time >= #{beginTime}
    and o.create_time <= #{endTime}

        and (o.response_breached = 1 or o.resolve_breached = 1
             or (o.resolve_deadline is not null and o.resolve_deadline < now() and o.status in (1,2,3,4,5,6,8)))


        and ifnull(o.response_breached, 0) = 0 and ifnull(o.resolve_breached, 0) = 0


order by field(o.status, 1, 2, 3, 4, 5, 6, 8, 7, 0), o.priority desc, o.create_time desc

select d.plan_date as date,
       (select count(*) from wo_order o where date(o.create_time) = d.plan_date) as created,
       (select count(*) from wo_order o where o.status = 7 and date(o.complete_time) = d.plan_date) as completed
from (
    select date(create_time) as plan_date from wo_order
     where create_time >= #{begin} and create_time < #{end}
    union
    select date(complete_time) as plan_date from wo_order
     where status = 7 and complete_time is not null
       and complete_time >= #{begin} and complete_time < #{end}
) d
order by d.plan_date
